ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_8"] = {
{"r2_mis_twenty_five_hundred","military_mistake",5,9,0,5,1,{"Anvil-2-4","Anvil-2-6, Anvil-2-4, relief for the east post is late - they were due at 2500 hours, over","Anvil-2-6","Say again the time, over","Anvil-2-4","2500 hours, over","Anvil-2-6","Anvil-2-4, there is no such time as 2500 hours - when did you last sleep, over?","Anvil-2-4","Stand by, I'm counting - Thursday - no - what's today, over?","Anvil-2-6","Today is {weekday}, hand your radio to your team leader and lie down in the truck, over","Anvil-2-4","My team leader's the one who told me 2500, over","Anvil-2-6","Then both of you lie down, I'm sending Sergeant Pike to the east post - Anvil-2-6, out"}},
{"r2_mis_sitrep_coffee","military_mistake",5,8,8,18,1,{"Warden Main","Crowbar-3-4, Warden Main, send SITREP, over","Crowbar-3-4","Roger, enemy, everybody who isn't us - friendly, us, there are three of us, over","Warden Main","Crowbar-3-4, use the format, over","Crowbar-3-4","That's the format, Warden Main - line one enemy, line two friendly, I gave you both, over","Warden Main","Send location, activity and needs, over","Crowbar-3-4","Location, the feed store, activity, still fixing the tire - needs, the man here wants to know if the Army pays for coffee, over","Warden Main","Negative on the coffee - Warden Main, out","Marty","It was on the house, I'd like that entered into whatever log they keep"}},
{"r2_mis_still_on_fire_channel","military_mistake",5,8,6,12,1,{"Striker-12","Anybody on this channel, this is Striker-12, checking in, still at the Brandenburg overpass, over","Knox Dispatch","Morning, Striker-12, you're on county fire again, sweetheart - go ahead","Striker-7","Striker-12, Striker-7, you are still on the civilian band - switch to your assigned net, over","Striker-12","Sergeant, nobody has answered on the assigned net since Tuesday - on this channel, somebody answers, over","Striker-7","Striker-12, that is not how the Army works, over","Striker-12","Roger - Sergeant, you're on the civilian band too, over","Striker-7","Stand by","Striker-7","Dispatch, Striker-7 - you have room on your channel for two more, over?","Knox Dispatch","Plenty of room, hon - weather's ninety-six and no rain, that's all the news I've got - dispatch clear"}},
{"r2_d5_first_one_added","military",5,8,4,10,2,{"Striker-1-6","Warden Main, Striker-1-6, for the log - at 0412, at my barrier, a Category One was born - female, over","Warden Main","Say again, born, over?","Striker-1-6","Born, about six pounds, we weighed her against a full canteen and a half - mother is stable, over","Warden Main","Roger - how do I log her, over?","Striker-1-6","Log her as a One, first One anybody's added since this started, over","Warden Main","Logged - does she have a name, over?","Striker-1-6","The mother says no names in the clear, she heard that on our radio, so you'll have to take my word that she has one, over","Warden Main","Taken - Warden Main, out"}},
{"r3_so_d5_mail_slot","sign_on",5,6,5,8,1,{"Marty","Ninety-nine point six, it's {weekday} morning, and this is Marty Colburn at the feed store","Marty","People have been pushing notes through my mail slot overnight - names, mostly, people looking for people","Marty","I meant to read them all this morning, there are forty-one - I'll read ten an hour so the generator lasts the day","Marty","If you leave a note, print it, I have one here that's either for Wanda or for Randall, and I'd hate to get that one wrong","Marty","First note, 'looking for Ricky Sizemore, drove the milk truck, last seen Friday.' Ricky, somebody's looking"}},
{"r3_sf_d5_both_words","sign_off",5,7,22,2,1,{"Marty","I'm not a praying man by habit, my wife Nancy handles that side of things for the both of us","Marty","She went up to her sister's in Louisville last Friday - she's up there, she was up there, I don't know which one to say, so I say both","Marty","If you do pray, put in a word for everybody who drove up to Louisville that weekend - there were a lot of us with somebody up there","Marty","Good night, ninety-nine point six, off the air"}},
{"r3_sf_d5_tomorrow_plan","sign_off",5,7,22,2,1,{"Marty","Here's tomorrow, as best I can plan it, six o'clock sign-on - scanner notes, names from the mail slot - the water instructions again","Marty","Again, because some of you missed them, and because repeating myself is the one job I'm sure I can do","Marty","The generator goes off in one minute, if you're sitting in the dark, stay in the dark - no lights facing the road","Marty","Good night"}},
{"r3_host_d5_feed_for_people","host",5,7,9,17,1,{"Marty","Folks keep coming to the store asking what feed is safe for people - I'm going to answer it once, on the air, so I can quit answering it at the door","Marty","Whole shelled corn, you can cook, soak it overnight and boil it a long, long time - it won't be good, it'll be food","Marty","Anything that says medicated on the tag, no, that bag has a drug in it for the animal on the label, and you are not that animal","Marty","Rabbit pellets, you can, but all you'll get out of them is a bellyache - dog food, in a pinch, yes, I'm sorry to be the man telling you that","Marty","And I've got seed corn out back that's been treated - it's dyed pink, do not eat anything pink out of a feed store"}},
{"r3_host_d5_zero_answers","host",5,7,0,23,1,{"Marty","Let me tell you the questions people have asked me this week, and then how many I can answer","Marty","Is it in the water? Is it the Army? Do you catch it breathing? Is the President coming on TV? Is Louisville still there?","Marty","The number I can answer is zero, I've been standing behind this counter with my hands in my pockets for five days","Marty","Here's the one thing I'm sure of, every person I've heard of who got bit got sick - so whatever else it is, don't let one get its teeth in you"}},
{"r3_host_d5_deputy_dollar","host",5,7,0,23,1,{"Marty","A sheriff's deputy stopped at the store this afternoon, first uniform I've laid eyes on since Saturday","Marty","He asked if he could use my bathroom, that was the whole visit, he used it, washed his face, and stood by the ice machine a while, even though it's not running","Marty","I asked him what the sheriff's office wants people to do - he said, 'Marty, I would love to know'","Marty","He took two bottles of water and tried to pay me - I wouldn't let him, he left a dollar on the counter anyway, under the tape dispenser","Marty","I'm leaving it right where it is"}},
{"r3_host_d5_orange_sky","host",5,7,20,23,1,{"Marty","If you're up on a hill tonight and you look north, you'll see the sky's orange - it's been that way two nights now","Marty","A man told me it's the chemical plants on the west end of Louisville - a woman told me it's the whole city, I'm not going to tell you either one","Marty","What I will tell you is it's a long way off, and the wind's been out of the southwest, so the smoke's blowing away from us","Marty","That's the good news I've got tonight, the smoke is going to somebody else","Marty","I hear how that sounds"}},
{"r3_host_d5_cb_first_caller","host",5,7,9,20,1,{"Marty","I've done something that may or may not work, I've set the CB microphone right up against this one, so if you call me on channel nineteen, the whole county hears you","Marty","Lloyd would have done it proper, with wires, I've done it with a stack of phone books and a rubber band","Marty","Let's try it, anybody on nineteen, go ahead","Caller - Gary","Yeah, uh, breaker one-nine - is this the radio man? This is Gary, out past the quarry","Marty","Gary, you're on the air, everybody can hear you","Caller - Gary","Oh, well, I didn't have anything to say - I just wanted to see if it worked","Marty","It works, Gary","Caller - Gary","Hi, Mom"}},
{"r3_ins_d5_say_names","instruction",5,7,5,9,1,{"Marty","One more thing, and it's a small one, every morning and every night, count the people in your house out loud","Marty","Say each name, wait till each one answers you","Marty","A man told me his neighbor's boy climbed out a window Tuesday night to go find his girlfriend, and nobody knew he was gone till noon","Marty","Count your people, morning and night - it takes a minute, and you'll sleep better for it"}},
{"r3_wx_d5_high_water","weather",5,7,5,10,1,{"Marty","We got an inch and a quarter in my gauge overnight, and I hear some of you got more - that's drinking water, catch it, cover it, boil it","Marty","It's cooler this morning, if you call seventy-two cooler, by afternoon the steam will be coming right back up off the blacktop","Marty","A caller says their creek has flooded. We can't verify conditions at your location. Don't count on water to keep you safe","Marty","I don't know if it came out the other side - I didn't wait to see, that's the weather this morning"}},
{"r3_mb_d5_market_report","music_bridge",5,7,0,23,1,{"Marty","A little filler while I put new paper in the notebook - call it the market report","Marty","Layer pellets, as of today, cost whatever you'd trade me for them - sweet feed, the same, a fifty-pound bag of dog food, one working flashlight or one good story","Marty","Mineral blocks are free, since nobody can get out to their cattle","Marty","Market's closed - back to it"}},
{"r3_sil_d5_chair_scrape","silence",5,7,0,23,1,{"99.6 FM","(Static, then a chair scraping back, footsteps going away, and static again)"}},
{"r4_sad_tractor_washed","caller_story_sad",5,8,17,22,1,{"Caller - Bobby","Hello? Am I on? My wife said just talk, you'll know if you're on","Marty","You're on, sir","Caller - Bobby","Well, it was my grandson's birthday today - six - Wednesday the fourteenth","Caller - Bobby","I promised him a ride on the tractor for it - real ride, on my lap, him steering, all the way down the back field","Caller - Bobby","He's up in Louisville with his mama, they were going to drive down this morning","Caller - Bobby","I washed that tractor yesterday - Waxed the fenders - put a bow on the seat, one of those stick-on ones off a Christmas box","Caller - Bobby","Didn't start it today, wasting gas, with things how they are","Caller - Bobby","I just sat up on it a while in the barn","Marty","Happy birthday to your grandson, sir","Caller - Bobby","His name's Cody, happy birthday, Cody","Marty","(The carrier stays open a few seconds with nothing on it)"}},
{"r4_hor_well_bucket","caller_story_horror",5,8,23,4,1,{"Caller - Opal","Our house is on a well, the old hand well out back still works, from before we had the pump - that's how we've had water","Caller - Opal","Last few days the water's had a taste, kind of sweet, kind of like pennies - we boiled it anyway","Marty","Oh no","Caller - Opal","Tonight I dropped the bucket and it didn't splash, it hit something soft, then the rope jerked in my hands","Caller - Opal","Something down there took hold of the bucket, and it pulled, I dug my heels in and it pulled and pulled","Caller - Opal","I let go, the rope went down the hole, I heard the bucket bang the rocks all the way to the bottom","Caller - Opal","I have been drinking that water for four days, Marty - my grandbabies have been drinking it","Caller - Opal","Now I hear it down there - echoing up - hands on the wet stones - Slipping and trying again","Marty","Put the lid on it, put something heavy on the lid - don't drink any more of it","Marty","(Marty is silent, then he asks, very quietly, whether anybody knows if boiling is enough - no one calls in to answer)"}},
{"r4_hor_marty_back_door","caller_story_horror",5,8,1,4,1,{"Marty","This is Marty, I'm going to tell you something that happened here tonight at the store, and I want you to know I'm alright","Marty","The feed store has a loading door out back, a big roll-up, I keep it chained, it rattles if you look at it","Marty","About midnight it started rattling - soft - Rhythmic, I thought it was a raccoon - we get raccoons in the grain","Marty","I took the flashlight and went to the gap at the bottom - there's about two inches where the door doesn't meet the concrete","Marty","There were fingers in the gap, lots of fingers, all along the door, just the tips, working back and forth, trying to lift it","Marty","I counted to twenty and then I made myself stop counting - they were all different sizes, some of them were very small","Marty","I put fifty-pound sacks of sweet feed along the bottom of that door - thirty of them, my back is shot","Marty","The rattling stopped around two, I think they went on, I think they went on","Marty","I'm going to keep broadcasting because I don't know what else to do with my hands","Marty","(Marty's voice cracks on the word hands, he clears his throat and doesn't try again for a while)"}},
{"r7_mil_sitrep_all_zeros","military",5,8,5,10,2,{"Cardinal Main","Cardinal-2-6, Cardinal Main, send your morning SITREP, over","Cardinal-2-6","Roger, line one, personnel - authorized forty-two, present eleven, over","Cardinal Main","2-6, say again line one, over","Cardinal-2-6","Present eleven, line two, ammunition on hand - none, line three, water - none, line four, rations - none, over","Cardinal Main","Continue, over","Cardinal-2-6","Line five, vehicles, one, and it won't start without a push - line six, comms, this radio and this battery, over","Cardinal Main","2-6, line seven, over","Cardinal-2-6","Line seven, mission capable - negative - Cardinal Main, I can hold this barrier until dark by standing in the road and looking serious, over","Cardinal Main","Roger your SITREP, 2-6, it is written down exactly as you sent it, over","Cardinal-2-6","That's all I wanted out of it - Cardinal-2-6, out"}},
{"r7_nights_sheriff_takes_a_car","scanner",5,7,21,2,1,{"Knox 1","Knox County, Knox 1 - show the sheriff in a car tonight, I'll take the north end","Dispatch","Knox 1, copy - Sheriff, you ain't rode nights since I've worked here","Knox 1","I ain't had four deputies since you've worked here either - Knox 20, you keep the south and I won't get in your way","Knox 20","Knox 20 copies - Sheriff, the north end's where we lost Teague","Knox 1","I know where we lost him, that's why I'm taking it - show me 10-8 at {time}","Dispatch","10-8 at {time} - Sheriff, your wife called the office twice tonight","Knox 1","I'll call her from the office phone when I come back in - don't put that on channel 2 either"}},
{"r7_ksp_go_to_the_alternate","scanner",5,7,6,22,2,{"Post 4","All Post 4 units, stand by for a frequency change - effective at {time}, all car to car traffic goes to the alternate","Trooper 418","Post 4, 418 - which alternate? There's two knobs and one of them's been broke since spring","Post 4","The second position, the one nobody has ever used - check in on it one at a time when I call your number","Post 4","406","Trooper 406","406 on the alternate, loud and clear","Post 4","418","Trooper 418","418 on the alternate, I can hear a radio station behind you, Post 4 - somebody's playing gospel music under your voice","Post 4","I hear it too, live with it. 422, are you there?","Post 4","422. 422, Post 4","Post 4","All units, 422 does not have the alternate, anybody who reaches him, tell him to come to the post - post 4 out"}},
{"r7_ksp_teletype_last_message","scanner",5,8,4,10,1,{"Post 4","All units, the teletype came back up for about four minutes this morning and then it quit again","Trooper 406","Post 4, did anything come through?","Post 4","One message, it was a stolen vehicle entry out of Owensboro from the eighth","Trooper 406","That's all?","Post 4","That's all, a blue Cutlass, and a plate, and a phone number to call with information","Trooper 406","Post 4, are you going to look for a blue Cutlass?","Post 4","I taped it to the wall, 406, somebody in Owensboro sat down and typed that out on the eighth and I'm not throwing it in the trash"}},
{"r7_fire_grass_along_31w","scanner",5,8,13,20,1,{"Dispatch","Brush 32 and Tanker 44, grass fire in the right of way on 31W south of the weigh station - about a quarter mile of it","Brush 32","Brush 32 en route - dispatch, is it threatening anything?","Dispatch","There's a line of cars parked in the grass along there - people sleeping in some of them","Brush 32","Brush 32 on scene - get somebody down here to bang on windows, half these cars have got folks laying in the back seat","Tanker 44","Tanker 44, two minutes out","Brush 32","Dispatch, this started at a cook fire in the ditch - ain't a thing malicious about it, somebody was making supper","Dispatch","Brush 32, do you want the sheriff out there?","Brush 32","No, I want a hundred feet of hose and somebody to tell these people the ditch ain't the place for a fire - I'll tell 'em myself"}},
{"r8_hor_living_room_in_31w","caller_story_horror",5,60,21,3,1,{"Delbert","I got no business calling but here I am","Delbert","Somebody hauled a whole living room out to the middle of 31W, south end of Muldraugh - couch - lamp, coffee table with a doily on it","June","Blocking the road?","Delbert","No, that's the thing, it's all set up, like a room - couch behind the table, lamp at the end, all of it facing north","Delbert","You could sit down in it, a fella could sit down on that couch and look up the highway","June","Did you?","Delbert","No, no, I walked around the far shoulder in the weeds and I didn't look at it twice","Delbert","And then it got light out and I got where I was going - that's all that happened"}},
{"r8_hor_screen_door_hooked","caller_story_horror",5,60,23,5,1,{"Opal","Am I on? Okay - okay - so you know the trailers back of the Sav Rite? Where the gravel turns?","June","Go on","Opal","Third one down, windows busted out, front of it's been open to the rain for weeks, you can see the couch got mold on it","Opal","Screen door's hooked, from the inside, that little hook and eye, you know the kind","June","Somebody could have hooked it and gone out a window","Opal","They could've, I thought that - I thought that for two days","Opal","And then Saturday it was unhooked, and Sunday it was hooked again - same little hook","Opal","So somebody's going in and out and locking up after theirself - I don't need to know who, I want to not know who"}},
{"r8_hor_chainsaw_two_days","caller_story_horror",5,60,22,4,2,{"June","Line's open","Gilbert","There's a chainsaw running somewhere south of us, two days now","June","Running the whole time?","Gilbert","Not steady, it'll rev up, cut, idle a while - cut again, like a man working, but it don't quit at dark and it don't quit at all","Gilbert","A saw don't run two days, gas, bar oil, a chain that wants filing - I run a saw for a living twenty-two years","June","Somebody clearing a road, maybe - in shifts","Gilbert","Could be, I thought that, then last night it come from the east instead of the south, and it was the same saw","Gilbert","You know a saw by its sound the way you know a voice - it's the same saw","Gilbert","So we ain't going south and we ain't going east - that's where we're at now"}},
{"king_radio_old_apology","caller_story_sad",6,3650,0,23,1,{"Mara","I owe somebody an apology. Don't know where to send it","June","Do you want to say it here?","Mara","Not the whole thing","June","You don't have to","Mara","I was trying to win. I should've been listening","June","That's a hard thing to notice","Mara","It took me long enough","June","I hope you get to tell them"}},
{"king_radio_just_a_question","caller_story_sad",6,3650,0,23,1,{"Eli","Somebody asked my favorite color. I thought they were making fun of me","June","Were they?","Eli","No. They just wanted to know","June","What did you tell them?","Eli","Green. Then I asked theirs","June","Did it help?","Eli","Didn't fix anything. I didn't expect it to","June","Still sounds like a good conversation"}},
{"king_radio_bad_neighbor","caller_story_horror",6,3650,0,23,1,{"Clive","We used to argue about his lawn mower. Seven every Sunday morning","June","Your neighbor?","Clive","Yeah. Last time I saw him I nearly called across the fence","June","What stopped you?","Clive","He wasn't walking right. I knew before he turned around","June","You don't have to go on","Clive","I just wish the last thing I'd said to him wasn't about the mower","June","He probably knew you better than one argument"}},
{"king_radio_kitchen_argument","caller_story_sad",6,3650,0,23,1,{"Doreen","We had a terrible fight over who was supposed to sweep the kitchen","June","Recently?","Doreen","No, before. I can't even remember which of us was right","June","Does it matter now?","Doreen","I want it to. I want that to be the worst thing we had to fight about","June","Yeah","Doreen","Sorry. Thought I had a funny story when I called","June","You don't owe us a funny one"}},
{"r2_d6_hammer_says_names","military",6,6,0,23,1,{"Hammer-3-7","Hammer-3-1, Hammer-3-7, radio check, over","Hammer-3-7","Reyes - Reyes, it's Sergeant Boone - pick up the handset, over","Hammer-3-7","Tucker - Lindqvist - anybody, I don't care about callsigns, just answer me, over","Warden Main","Station using personal names on this net, identify yourself, over","Hammer-3-7","Hammer-3-7, over","Warden Main","Hammer-3-7, no names in the clear - clear the net, over","Hammer-3-7","Warden Main, there are nine of them, they've been out at that water plant three days, I'd like to say their names one time, over","Warden Main","Hammer-3-7, I understand - clear the net - Warden Main, out","Hammer-3-7","Hammer-3-7, clearing - out"}},
{"r2_d6_leave_it_with_him","military",6,7,8,16,2,{"Crowbar-6","Crowbar-2-6, Crowbar-6, prepare to displace - TCP 5 collapses back to the river line at 1500 - acknowledge, over","Crowbar-2-6","Acknowledged - Sir, what about the holding tent? I have thirty-one Category Ones in it, over","Crowbar-6","They stay, there's no transport and no room on the river line for them, over","Crowbar-2-6","Sir, for four days they've been told we're the ones keeping them safe, over","Crowbar-6","I know what they've been told - leave the water and whatever rations won't fit in your trucks, over","Crowbar-2-6","And the rifles from the two soldiers we lost, over?","Crowbar-6","Wait one","Crowbar-6","Crowbar-2-6, find the most sensible adult in that tent - show him how to load it, then leave it with him - Crowbar-6, out"}},
{"r2_d6_two_thousand_feet","military",6,8,0,23,1,{"Warden Air","All aviation, Warden Air, effective now, no flight below two thousand feet over populated areas - rotor noise is drawing Category Threes toward the people underneath, over","Bluejay 2-6","Bluejay 2-6, roger, for the record, I flew low over Rosewood yesterday to see if folks were alright, over","Warden Air","Understood - were they, over?","Bluejay 2-6","They were waving bedsheets off the roofs, this morning the streets under my route are full, over","Warden Air","That's not on you, Bluejay - nobody knew, two thousand feet from here on, over","Bluejay 2-6","Two thousand feet, from up there I won't be able to tell the ones waving from the ones walking - Bluejay 2-6, out"}},
{"r2_d6_sandlot_one_meal","military",6,7,6,12,1,{"Sandlot","Warden Main, Sandlot - count follows - Category One, one hundred four - Category Two, none, over","Warden Main","Say again, Twos none, over?","Sandlot","None, nobody's admitting to a scratch anymore - they hide it, and then it happens at night up in the bleachers, over","Warden Main","Roger, recommend you inspect at every meal, over","Sandlot","There's one meal a day now, we inspect at that one - people skip it so they don't have to show their arms, over","Warden Main","Understood - what do you need, over?","Sandlot","A way to tell a hundred and four people they aren't going anywhere - you don't have one of those on a pallet, over","Warden Main","Negative - Warden Main, out"}},
{"r2_d6_hill_fuel_left","military",6,8,8,13,1,{"Hatchet-6","Relay Hill, Hatchet-6, radio check, over","Warden Main","Hatchet-6, Warden Main, I have you loud and clear through the retrans, over","Hatchet-6","Then the hill's still up - has anyone heard from the two soldiers on it, over?","Warden Main","Negative - Reaction force reported the shelter door shut and the generator running - they didn't open the door, over","Hatchet-6","Roger - how much fuel was in that generator, over?","Warden Main","Full tank at 1800 yesterday, figure twenty hours, over","Hatchet-6","So we have until about two this afternoon to say anything important, over","Warden Main","Affirmative - Hatchet-6, I'd go ahead and say it - Warden Main, out"}},
{"r2_d6_turbine_dinner_bell","military",6,8,0,23,1,{"Warden Main","Hatchet-6, Warden Main - why is your tank running at TCP 2, over?","Hatchet-6","Its batteries are weak, if we shut it down, we may never get the turbine lit again, over","Warden Main","Every Category Three within two miles can hear that turbine, over","Hatchet-6","I know, they're crossing the pasture in a line toward the sound - the tank doesn't mind, the soldiers standing next to it mind a great deal, over","Warden Main","Shut it down, a tank that doesn't move is a bunker - a tank that whines all day is a dinner bell, over","Hatchet-6","Roger, shutting down, crew stays inside with the hatches closed - Hottest seat in the county, over","Warden Main","Roger - Warden Main, out"}},
{"r2_d6_chaplain_walks_line","military",6,8,17,22,1,{"Chaplain","All Hatchet stations, this is the battalion chaplain, on your net with the commander's permission - I'm coming down the line tomorrow on foot, over","Hatchet-6","Chaplain, I'd rather you didn't walk it, I can't spare you an escort, over","Chaplain","Noted, Captain, stations, tell me one thing you need that I could carry - keep it light, over","TCP 2","TCP 2, dry socks, Chaplain, over","TCP 3","TCP 3, foot powder and cigarettes, over","Hatchet Overwatch","Overwatch, somebody to tell us it wasn't wrong, over","Chaplain","Socks, powder, cigarettes, the last one I'll carry myself - chaplain, out"}},
{"r2_mis_marty_lessons","military_mistake",6,10,17,22,1,{"Marty","A few of you have left notes in the mail slot at the feed store asking what the soldiers keep getting wrong - I'm no expert, but I've had a week of lessons","Marty","You say over when you're done talking and want an answer - you say out when you're done talking and don't care to hear another word - some of their officers use out a great deal","Marty","Never say repeat, as best I can tell, repeat means something to the mortar crews - say again instead, I've started saying it to my dog","Marty","And a goat is not a Rover, that one came straight from a lieutenant, and I believe he meant it","Marty","Most of them are young, they're making the mistakes you'd make if the world changed on a Friday and somebody handed you a radio on Saturday - go easy on them"}},
{"r3_so_d6_say_it_twice","sign_on",6,7,5,8,1,{"Marty","Good morning, it's {time} - I've been up since three, so if I read you something twice, somebody call in and tell me","Marty","Nobody can call in, the phones are out, so I suppose you'll just hear it twice","Marty","The scanner was quieter last night than any night so far - I'd like to tell you that's good news, I don't know that it is","Marty","I'm keeping to the schedule anyway, on the hour, what I've heard, on the half hour, what you can do about it"}},
{"r3_sf_d6_fire_hall_siren","sign_off",6,7,22,2,1,{"Marty","The siren on the fire hall ran for about a minute tonight and then quit - I don't know who ran it, I don't know why it stopped","Marty","If that was you, and you were trying to get somebody's attention, I heard it - that's all I can give you","Marty","Everybody else, don't go down to the fire hall in the dark to find out - go in daylight, or don't go","Marty","I'm shutting down for the night, this is Marty Colburn"}},
{"r3_host_d6_sevens_crossed","host",6,7,0,23,3,{"Marty","I need to read something that came through the mail slot - it's an answer to one of the notes I read on Wednesday","Marty","On Wednesday I read a note from a woman named Pauline, looking for her boy Tommy, who works at the tire shop in Muldraugh","Marty","This morning there's a note in Tommy's hand, I know it's his, he's been writing checks at my counter for years, and he crosses his sevens","Marty","It says, 'Mama, I'm at the Methodist church in Rosewood - heard it on the radio - stay put, I'm coming to get you'","Marty","I had to sit down on a sack of sweet feed for a minute - I'm alright now - Pauline, if you're hearing this, stay put"}},
{"r3_host_d6_bathtub_caller","host",6,7,19,23,3,{"Caller - Lynette","Radio man, are you there? This is Lynette, I'm in the trailer park behind the laundromat in Muldraugh","Marty","I'm here, Lynette - go ahead - keep your voice down if you need to","Caller - Lynette","There's four of them between the trailers, they keep bumping the skirting, my husband went out at three to find gas and he's not back","Marty","Is your door locked? Are you away from the windows?","Caller - Lynette","I'm in the bathtub with the baby, it's the only room with no window","Marty","Then you did it right - stay in the tub - don't answer anything that knocks, your husband has a key","Caller - Lynette","He does, he does have a key - okay","Marty","I'll sit on nineteen with you as long as the battery goes - you don't have to talk, just key up twice every little while so I know","99.6 FM","(Two short clicks)"}},
{"r3_host_d6_white_rags_ask","host",6,6,9,17,1,{"Marty","I've been doing this six days and I have no idea whether anybody is listening past the end of my driveway","Marty","So here's what I'm asking, if you hear me, tie something white to your mailbox - a rag, a pillowcase, a cloth diaper, whatever you've got","Marty","Tomorrow at noon I'm going to drive the truck one mile each way on the main road, slow, and count mailboxes","Marty","I won't stop and I won't honk, I just want to know how many of you there are"}},
{"r3_wx_d6_lightning_bugs","weather",6,7,5,9,1,{"Marty","Weather, and one thing that isn't weather","Marty","Hot again, ninety or so - clear this morning, clouds building out of the west after dinner, and a thunderstorm possible by four","Marty","The thing that isn't weather, last night, for the first time all week, there were lightning bugs over the back field - a whole lot of them","Marty","I stood out on the loading dock and watched longer than I should have - anyway - keep your water in the shade today"}},
{"r3_mb_d6_invoice_humming","music_bridge",6,7,0,23,1,{"Marty","A song would fit right here, my wife would be humming one about now, doing the invoices at the desk behind me - never the whole thing, just the part she knew","Marty","Thirty-one years, and I never once asked her what it was called","Marty","Give me a minute, we'll pick back up"}},
{"r3_sil_d6_fell_asleep","silence",6,7,1,5,1,{"99.6 FM","(The carrier is on, someone is breathing slow and even, close to the microphone)","Marty","I fell asleep - I'm sorry, I don't know how long the transmitter was on, I'm shutting it off now"}},
{"r4_hor_radio_asks_back","caller_story_horror",6,8,2,4,1,{"Caller - Unknown","(The signal is weak, a man's voice, very close to the microphone)","Caller - Unknown","You said you'd stay on - earlier, you said to somebody, I'll stay on the line","Marty","Yes sir, I say that - who am I speaking with?","Caller - Unknown","I've been listening every night, I've been writing down what people tell you, where they are - the road, the trailer park - the pontoon","Marty","Sir, I need you to not do that","Caller - Unknown","I'm not going to hurt anybody - I'm not, I'm just going to go sit with them, at the end - so they're not alone like they said","Caller - Unknown","The man in the tree, I went there, I sat at the edge of the woods, I watched him the whole time - he wasn't alone","Marty","What do you mean, the whole time?","Caller - Unknown","Tomorrow, where should I go? Who else needs somebody? You're the one who knows - you tell me","Marty","(Marty turns off the transmitter, when it comes back on nine minutes later, he doesn't mention the call)"}},
{"r7_mil_sitrep_read_it_back","military",6,9,5,11,1,{"Cardinal-3-6","Cardinal Main, 3-6, before I send this, I want you to read it back to me when I'm done, over","Cardinal Main","3-6, send it, over","Cardinal-3-6","Nine present of thirty-one - two buried at church, four home, rest unaccounted - no ammo, no water since Tuesday, over","Cardinal Main","Nine of thirty-one, two dead, four departed, balance unaccounted - no ammunition, no water since Tuesday - is that your report, over?","Cardinal-3-6","That's my report - say the two dead part again, over","Cardinal Main","Two dead and buried at the church, over","Cardinal-3-6","Their names are Ruiz and Ledford, and I want the names in your log and not just the number two, over","Cardinal Main","Ruiz and Ledford, they're in the log in ink, 3-6 - Cardinal Main, out"}},
{"r7_nights_one_car_with_fuel","scanner",6,8,0,5,2,{"Knox 20","Knox County, Knox 20, as of {time} we're down to one car with fuel in it and that's mine","Dispatch","Copy, Sarge - what do I do with the calls?","Knox 20","Read 'em to me and I'll pick, that's the job now, and I hate the sound of it on the air","Dispatch","I got fourteen holding","Knox 20","Any with a child in them?","Dispatch","Three","Knox 20","Then read me those three and hold the rest - Knox 20 en route to the first one you say"}},
{"r7_school_base_signs_off","scanner",6,10,16,21,1,{"Base","Base to any bus on this channel, this is the transportation office at the county garage, I'm going home in about an hour","Base","There's four buses parked here with diesel in them, keys are in the office in the coffee can on the shelf, not the one on the desk","Base","They start cold if you pump it twice and wait - number 9's got a soft brake, so don't take 9 down a hill with people on it","Base","The attendance books are in the box under the counter - every name anybody wrote down since Sunday is in that box, and it's alphabetized now","Bus 12","Base, Bus 12, I'm still out here, I'm at the fairgrounds with a half a tank","Base","Wanda, go home to your boy","Bus 12","I will, base, I'm gonna run the trailer park one more time first - there's folks out there still standing at the stop","Base","Then I'll wait on you before I lock up, base standing by"}},
{"r8_hor_somebody_swept","caller_story_horror",6,90,23,5,2,{"Odell","I won't take long. You got people waiting","Odell","House on Halbert Street - picked clean, which, fine, that's normal now, I ain't complaining about that part","Odell","But somebody had swept","June","Swept","Odell","Little pile of glass in the corner, broom set against the wall, handle up, like you'd leave it in your own kitchen","Odell","Whoever picks a house clean doesn't stop to sweep. That's twenty minutes. What'd they want it tidy for?","June","I don't have anything for that","Odell","I can't explain it either. I don't go in if it's tidy now. You do what you like"}},
{"r8_hor_bikes_wheels_in","caller_story_horror",6,70,22,4,2,{"Marvis","I'll say it plain and then you can do what you want with it","Marvis","Yard on Halbert Street, the one with the basketball goal - five bikes laid down flat in a circle in the grass","June","Laid down how?","Marvis","On their sides, in a ring, every front wheel pointed in at the middle","Marvis","Kids don't lay a bike down, kids drop a bike wherever their feet hit the ground, my three did","June","What was in the middle?","Marvis","Nothing - grass, that's what I looked at the longest, is the nothing","Marvis","I ain't saying anybody did it on purpose, I'm saying somebody carried five bikes in off that street"}},
{"r8_hor_doll_shoe_mailboxes","caller_story_horror",6,80,22,4,2,{"June","You're on ninety-nine six, nobody's going to rush you","Merle","I walk the mailboxes, that's how I eat, folks quit getting mail, there's checks and coupons and sometimes a can in a care package","June","All right","Merle","Out the Ekron road, four boxes in a row had a doll's shoe in 'em","Merle","Little white one, buckle on it, same shoe four times, I mean the same kind, all lefts","June","Four in a row","Merle","One, two, three, four, right down the road, and then the fifth box had nothing and I quit looking in boxes","Merle","That was the twelfth - Monday, day after the water quit, so I know the day","Merle","I eat different now, that's about all it did to me"}},
{"r8_hor_three_scratches_door","caller_story_horror",6,70,0,5,1,{"Herschel","Storm door on the back of the house - aluminum one","June","Something's at it?","Herschel","Three new scratches on it every morning, down low, about knee high - three, not four, not two","Herschel","Six days - eighteen scratches, I went out there and counted 'em with my finger like a fool","June","Have you heard anything at night?","Herschel","Not a sound, and I'm a light sleeper, my wife'll tell you, a cat on the porch wakes me","June","Can you sleep in a room away from that door?","Herschel","We moved to the front room the second night, the scratches kept on at the back door anyhow","Herschel","Probably a coon - probably, I nailed a piece of plywood over it and I'll be checking that in the morning"}},
{"r8_hor_water_running_no_pressure","caller_story_horror",6,70,0,4,1,{"Bonnie","Am I on? I can hear myself, let me turn this down","June","You're fine - go ahead","Bonnie","House two doors up, nobody in it since the tenth, I watched them load the car myself","Bonnie","Water's running in it, you can hear it from the sidewalk, a tap wide open in the back of the house","Bonnie","Nine days without water here. My tap spits, that's it. Everybody on this street's carrying water from the creek","June","Somebody could have a tank","Bonnie","Nine days, June, it's run nine days - no tank in a kitchen holds nine days of a wide open tap","June","I'd stay on your own side of the street","Bonnie","I stay on my side. Keep the radio on, quit looking at that house once it's dark. I haven't come up with anything better"}},
{"exp_measuring_wall","caller_story_sad",7,3650,0,23,1,{"Glenn","We measured the kids against the laundry room wall every birthday","June","Pencil marks and dates?","Glenn","Different colors, my daughter insisted each year needed its own color","June","That sounds like quite a wall","Glenn","I painted the rest of the house twice, never touched that room","Glenn","I can't carry a wall around with me, can I?","June","No, I'm sorry, Glenn","Glenn","Just wanted to say it was there, blue was the last mark"}},
{"exp_daughters_spelling","caller_story_sad",7,3650,0,23,1,{"Glenn","My daughter spelled my name wrong on a birthday card","June","Was she very little?","Glenn","Little enough that the letters went uphill","Glenn","I didn't correct her, figured she knew who she meant","June","She certainly did","Glenn","I've got official papers with my proper name - don't care about those","June","You kept the card?","Glenn","Inside my shirt, spelled wrong and everything"}},
{"exp_second_shadow","caller_story_horror",7,3650,21,5,1,{"Morris","I kept seeing a second shadow beside mine","June","Was there another light somewhere?","Morris","Probably, I didn't stay around to work it out","June","You sound unsure about what happened","Morris","I'm sure I was frightened, the rest keeps changing when I remember it","June","You don't have to turn it into a certainty for us","Morris","Good, I just needed somebody to hear why I can't settle down","June","We can believe you were frightened without guessing what made the shadow"}},
{"exp_baby_monitor","caller_story_horror",7,3650,20,5,1,{"Paula","We used to hear our neighbor through a baby monitor","June","Picked up the wrong signal?","Paula","Sometimes, mostly harmless things - a television, somebody calling upstairs","Paula","I turned it on after the phones stopped, thought I might hear them","June","Did anyone answer?","Paula","Couldn't tell, there was a sound I kept wanting to turn into words","June","Static can be hard to leave as static","Paula","I took the batteries out - put them back ten minutes later"}},
{"exp_diner_order","caller_joke",7,3650,0,23,1,{"Bess","I waited tables, could carry six plates and remember four complaints","June","Only four complaints?","Bess","The fifth one had to wait its turn","June","What did people complain about most?","Bess","Coffee temperature, usually while I was pouring it","June","Before they'd tried it?","Bess","Some folks liked to get ahead on their disappointment","June","An ability which has found plenty of work lately"}},
{"more_radio_watch_partners","military",7,3650,22,5,1,{"Private","Sergeant, you ever stop hearing things that aren't there?","Sergeant","Tell me what you heard","Private","Nothing now, I thought somebody said my name","Sergeant","How much sleep did you get?","Private","Uh... enough, Sergeant","Sergeant","Try a number instead","Private","Two hours - maybe","Sergeant","Tell your relief, and tell me before you get to two hours next time","Private","Didn't want anybody thinking I couldn't handle it","Sergeant","I'd rather hear you're tired than find you asleep standing up - understood?"}},
{"more_radio_dog_collar","caller_story_sad",7,3650,20,5,1,{"Donna","I've still got my dog's collar","June","What was the dog's name?","Donna","Biscuit, he hated biscuits - loved the butter off them","Donna","Licked them clean and left the biscuit on the rug - every damn time","Donna","He'd bring his lead when anybody raised their voice","June","Wanted everybody outside?","Donna","I think so, he'd just stand between us with it in his mouth - tail going","June","Oh, sweetheart","Donna","Don't, I'll cry, I'm trying to remember the funny stuff","Donna","The biscuits, let's just-- let's leave it with the biscuits"}},
{"more_radio_map_was_old","instruction",7,3650,0,23,1,{"June","A note about directions passed over this frequency","June","Please tell us WHEN you saw something, we keep having to ask","Earl","I learned that from a road somebody called clear","June","How old was their information?","Earl","They'd driven it before the trouble started","Earl","Didn't find that out till I'd made the turn, I asked, 'This morning?' He said, 'Last Thursday'","June","Oh, for heaven's sake, that's not the same thing","June","If you're guessing, say so, and if someone gives you directions, ask when they were there","Earl","Even if they get annoyed, wish I'd annoyed that fellow a little more","June","Okay, thanks, Earl - I needed to hear that one too"}},
{"more_radio_pockets_full","caller_joke",7,3650,0,23,1,{"Wade","I found a teaspoon in every pocket of my coat","June","Were you collecting them?","Wade","Apparently, every time I found one I thought I needed one","June","How many?","Wade","Seven, it's a good coat","June","Seven pockets? In one coat?","Wade","My wife asked what I'd do if eight people came to dinner","Wade","So now I can't throw any out, she'll count them - I know she will","June","Put them in a drawer, Wade, you don't have to wear them","Wade","Yeah, all right, the clinking's getting on my nerves anyway"}},
{"more_radio_extra_plate","caller_story_sad",7,3650,0,23,1,{"Bess","I keep setting out an extra plate","June","At supper?","Bess","Every time, doesn't matter what we're eating","Bess","I don't notice till I'm carrying it over - then, oh - right","Bess","My daughter puts it back without saying anything","June","Oh, Bess","Bess","Yesterday I asked her to leave it","June","Did she?","Bess","Yes, then she set out a cup too","Bess","We left it there, neither of us said why"}},
{"more_radio_scarecrow_hat","caller_joke",7,3650,0,23,1,{"Mack","Our scarecrow's wearing my good hat","June","Do you want it back?","Mack","Yes, but my wife says he looks respectable","June","How do you look?","Mack","Like a man whose scarecrow has his good hat","June","Could you trade?","Mack","He won't negotiate","June","Mack, go get your hat","Mack","Birds don't seem impressed either","Mack","Ungrateful little shits - sorry, June - am I allowed to say that?"}},
{"more_radio_bucket_argument","caller_joke",7,3650,0,23,1,{"June","Two people want to settle a disagreement about a bucket","Lyle","He keeps calling it his bucket","Pete","It's got my name on it","Lyle","In your handwriting, from this morning","June","Pete - did you just write your name on his bucket?","Pete","I took the trouble to label it","Lyle","I labeled his truck 'Lyle'","June","And how did that go?","Pete","We are discussing the bucket","Lyle","Then quit calling it yours! See what I'm living with, June?"}},
{"more_radio_chopshop_horn","caller_joke",7,3650,0,23,1,{"Ray","We once stripped a car and couldn't get the horn to stop","Ray","Middle of the night, mind you, trying not to wake anyone","Leon","You leaned on the steering wheel","Ray","Can I tell it? Can I fucking tell ONE story?","Leon","Then set the part where you blamed a ghost","Ray","For one second","Leon","You apologized to the car's previous owner","Ray","I said sorry to the ghost, if there WAS a ghost","Leon","We'd removed his doors","Ray","Exactly! You'd haunt somebody for less"}},
{"more_radio_tiny_sister","caller_story_sad",7,3650,0,23,1,{"Tiny","My little sister used to make me wear these paper crowns","Tiny","Had to tape two sheets together, big fucking head - always had it","Tiny","She'd charge me a cookie to attend her royal dinner","Tiny","She'd put a chair out, make me knock, in the kitchen, like I wasn't already in there","Tiny","Dinner was imaginary - cookie wasn't","Tiny","I always paid","June","I figured you did","Tiny","The people who know me now wouldn't believe any of this","Tiny","They'd never let me hear the end of it, big man in a paper hat","Tiny","Ah, fuck it - let them laugh, she thought I looked good"}},
}
